const crypto = require('crypto');
const item = $input.first();
const json = item.json || {};
const headers = Object.fromEntries(Object.entries(json.headers || {}).map(([k,v]) => [String(k).toLowerCase(), String(v)]));
const timestamp = headers['x-drop-rate-timestamp'] || '';
const supplied = headers['x-drop-rate-signature'] || '';
const secret = String($env.DROP_RATE_AUTOMATION_WEBHOOK_SECRET || '').trim();
const now = Math.floor(Date.now()/1000);
const ts = Number(timestamp);
let error = null;
if (secret.length < 32) error = 'secret_not_configured';
else if (!Number.isInteger(ts) || Math.abs(now-ts) > 300) error = 'stale_or_invalid_timestamp';
else if (!/^sha256=[0-9a-f]{64}$/.test(supplied)) error = 'invalid_signature_format';

let rawBody = '';
let body = null;
if (!error) {
  const encoded = item.binary?.data?.data;
  if (!encoded) error = 'raw_body_missing';
  else {
    try {
      rawBody = Buffer.from(encoded, 'base64').toString('utf8');
      body = JSON.parse(rawBody);
    } catch {
      error = 'invalid_json';
    }
  }
}
if (!error && (!body || typeof body !== 'object' || Array.isArray(body))) error = 'invalid_body';
const required = ['event_id','event_type','schema_version','aggregate','idempotency_key','occurred_at','payload'];
if (!error && required.some((key) => body[key] === undefined || body[key] === null || body[key] === '')) error = 'invalid_envelope';
if (!error && (!body.aggregate || !body.aggregate.type || !body.aggregate.id)) error = 'invalid_aggregate';
if (!error && (!Number.isInteger(body.schema_version) || body.schema_version < 1)) error = 'invalid_schema_version';
if (!error) {
  const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + rawBody, 'utf8').digest('hex');
  const a = Buffer.from(expected, 'ascii');
  const b = Buffer.from(supplied, 'ascii');
  if (a.length !== b.length || !crypto.timingSafeEqual(a,b)) error = 'signature_mismatch';
}
return [{json:{accepted:!error,error,event:body}}];
